function resetRun(){economyRunId=null;deathScene=null;player={...runnerState(1),...ownAppearance()};bots=Array.from({length:15},(_,i)=>({...runnerState(i+2),id:'bot-'+i,name:['Rio','Skye','Jett','Milo','Luna','Rex','Remi','Zara'][i%8],color:OUTFITS[i%3].color,outfit:OUTFITS[i%3].id,isBot:true,speed:8.4+levelById(level).worldIndex*.4+(i%3-1)*.08,lane:(i%3-1)*6,seed:i*.9}));time=0;worldTime=0;accumulator=0;lastResult=false;clearInput();view.clearRunners();view.load(courseId());$('progress-fill').style.width='0%';syncHUD();}
function syncLobby(){const p=profile.get(),l=levelById(level),o=OUTFITS.find(o=>o.id===p.outfit)||OUTFITS[0],complete=Object.keys(p.medals).filter(k=>p.medals[k]>0).length;document.documentElement.style.setProperty('--world-color','#'+l.theme.sky.toString(16));$('world-name').textContent=l.world.toUpperCase();$('course-name').textContent=l.name;$('level-number').textContent=String(level).padStart(2,'0');$('distance').textContent=l.distance.toLocaleString();$('hazard-count').textContent=l.hazardCount;$('gold-target').textContent=formatTime(l.gold);$('difficulty').textContent='●'.repeat(l.difficulty)+'○'.repeat(5-l.difficulty);$('wallet').textContent=p.coins.toLocaleString();$('xp').textContent=p.xp.toLocaleString();$('completed').textContent=complete;$('tour-fill').style.width=complete/50*100+'%';$('medal-total').textContent=Object.values(p.medals).reduce((a,b)=>a+b,0);$('runner-name').textContent=CHARACTERS.find(c=>c.id===p.appearance.character).name.toUpperCase();$('runner-description').textContent=p.appearance.top+' · '+p.appearance.bottom;$('guest-label').textContent=p.name;$('player-rank').textContent=p.xp>15000?'WORLD TOUR LEGEND':p.xp>5000?'TRAILBLAZER':p.xp>1500?'RISING STAR':'ROOKIE RUNNER';$('play').innerHTML=!graphicsAvailable?'CHECK GRAPHICS SUPPORT':(p.medals[level]?'BEAT YOUR BEST':'CONTINUE THE TOUR')+' <span><svg class="arrow-icon" aria-hidden="true" viewBox="0 0 24 24"><path d="M5 19 19 5M5 5h14v14"/></svg></span>';$('world-chapters').innerHTML=WORLDS.map((w,i)=>`<button class="world-chapter ${i===l.worldIndex?'active':''}" data-world="${i}" aria-label="Explore ${w.name}"><span class="world-dot">${p.unlocked<i*10+1?'⌁':String(i+1).padStart(2,'0')}</span><small>${w.name}</small></button>`).join('');$('mode-tour').classList.toggle('active',raceMode==='tour');$('mode-endurance').classList.toggle('active',raceMode==='endurance');$('mode-hint').textContent=raceMode==='tour'?'Shorter races. Tougher sections.':'Long-distance challenge. Checkpoint saves enabled.';document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>showMap(Number(b.dataset.world)));}
function syncHUD(){if(network?.mode==='relay')return;$('timer').previousElementSibling.textContent=network?.mode==='party'?'RACE TIME':'YOUR TIME';const l=levelById(level),c=buildLevel(level);$('race-level').textContent='LEVEL '+String(level).padStart(2,'0');$('race-world').textContent=l.world.toUpperCase();$('race-name').textContent=l.name;$('target-time').textContent='GOLD · '+formatTime(l.gold);$('timer').textContent=formatTime(time,true);$('checkpoint').textContent=`Checkpoint ${(player?.cp||0)+1} / ${c.checkpoints.length}${online&&network&&network.mode!=='party'?' · '+network.qualified+'/'+network.qualify+' qualified':''}`;$('remaining').textContent=Math.ceil(Math.max(0,l.distance-(4-(player?.z||4)))).toLocaleString()+' m left · '+(c.checkpoints[(player?.cp||0)+1]?Math.ceil(Math.max(0,(player?.z||4)-c.checkpoints[(player?.cp||0)+1].z))+' m to flag':'Final stretch');$('race-coins').textContent='● '+(player?.coins||0)+(raceMode==='endurance'?' / '+earningsCap(level,raceMode):'');$('progress-fill').style.width=progress(player?.z||4,level)*100+'%';const others=online?(network?.players||[]).filter(p=>!p.spectator):[player,...bots];const position=player?.rank||1+others.filter(b=>b.id!==player?.id&&!b.eliminated&&(b.finished||b.z<(player?.z||0))).length;$('position').innerHTML=position+'<small> / '+Math.max(1,others.length)+'</small>';$('pace').innerHTML=(mode==='race'&&!player?.finished?Math.round(player?.actualSpeed||0):0)+'<small> m/s</small>';if(network?.mode==='party'&&player?.spectator){$('position').textContent='—';$('remaining').textContent='Watching · race next';$('checkpoint').textContent='Watching · queued';$('progress-fill').style.width='0%';}}
