$('about').onclick=()=>modal('<span class="pill">BEAN DASH · ROOM REMIX</span><h2>Your room. Your rules.</h2><p>Bean Dash Online is an independent multiplayer game built with ChatGPT Work. In World Relay, friends alternate Runner and Shaper roles to carry a light across three islands, timing bridges, gates and wind against a two-minute storm. Friends vote Calm or Wild to remix moving hazards, recover at flags for free and stay together between short races. Explore 50 solo World Tour levels, long-distance Endurance and your own runner style.</p><p>Find a line through rolling wheels, fireball volleys, mountain trails and sea crossings. Collect coins, unlock looks, and chase your next medal. Private room codes bring your friends to the same starting line.</p><p>Guest progress stays in this browser. Live race rooms are temporary. No player account or download is required.</p><p>Technical credits: Three.js for 3D rendering, Outfit for typography, and ws for online connections. Their license notices are included with the project.</p>');
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)&&['race','countdown'].includes(mode))e.preventDefault();if(e.code==='KeyR'&&!e.repeat&&!online&&['race','paused','results','dying','revival'].includes(mode)){e.preventDefault();startSolo(false,true);return;}if(e.code==='Escape'){e.preventDefault();if($('modal').open){if(mode==='results')lobby();else if(!['waiting','revival'].includes(mode))closeModal()}else pause();return}if(!e.repeat&&mode==='race'){if(e.code==='Space')queuedJump=true;if(e.code==='ShiftLeft'||e.code==='ShiftRight')queuedDive=true}keys.add(e.code)});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearInput();if(!online&&['race','countdown'].includes(mode))pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(!online&&['race','countdown'].includes(mode))pause()}});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);if(b.dataset.key==='Space')queuedJump=true;if(b.dataset.key==='ShiftLeft')queuedDive=true});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(b.dataset.key))});
